<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_role('admin','receptionist'); $title=t('Reception dashboard');
$date=(string)($_GET['date']??today()); if(!valid_date($date)) $date=today();
// Include inactive doctors with existing bookings so their patients are never hidden from staff.
$doctors=query('SELECT * FROM doctors WHERE (active=1 AND archived_at IS NULL) OR id IN (SELECT doctor_id FROM appointments WHERE appointment_date=?) ORDER BY name',[$date])->fetchAll();
require dirname(__DIR__).'/includes/header.php';
?>
<main id="main" class="container section"><div class="section-heading"><div><div class="eyebrow"><?= e(t('AT THE HEART OF EVERY VISIT')) ?></div><h1><?= e(t('Let’s keep care moving.')) ?></h1><p class="muted"><?= e(t('Choose a doctor to check in patients and manage their queue.')) ?></p></div><span class="soft-tag"><?= e(date_label($date)) ?></span></div><form method="get" class="filter-bar"><label for="date" class="form-label mb-0"><?= e(t('Appointment date')) ?></label><input id="date" name="date" type="date" class="form-control" value="<?= e($date) ?>" required><button class="btn btn-outline-primary"><?= e(t('View doctors')) ?></button><a class="text-link" href="<?= e(url('reception/index.php')) ?>"><?= e(t('Today')) ?></a></form><div class="row g-4"><?php $shown=0; foreach($doctors as $d): $s=schedule_for((int)$d['id'],$date); if(!$s) continue; $shown++; $state=booking_state((int)$d['id'],$date); $counts=one("SELECT COUNT(*) total,COALESCE(SUM(status='Completed'),0) completed,MAX(CASE WHEN status='In Consultation' THEN token_number END) serving FROM appointments WHERE doctor_id=? AND appointment_date=? AND status <> 'Cancelled'",[$d['id'],$date]); ?><div class="col-md-6 col-xl-4"><article class="panel reception-card"><div class="person-cell mb-4"><img src="<?= e(doctor_photo($d)) ?>" alt=""><div><h2><?= e($d['name']) ?></h2><span class="muted"><?= e(t($d['specialization'])) ?></span></div></div><span class="soft-tag"><?= e($state['label']) ?></span><div class="queue-card-stats"><div><strong><?= e($counts['total']) ?></strong><span><?= e(t('Appointments')) ?></span></div><div><strong><?= e(time_label($s['consultation_start'])) ?></strong><span><?= e(t('Consultation starts')) ?></span></div></div><p class="small muted"><?= e(t('Now serving:')) ?> <strong><?= $counts['serving'] ? '#'.e($counts['serving']) : '—' ?></strong> <span class="float-end"><?= e(t('queue.completed',['count'=>$counts['completed']])) ?></span></p><a class="btn btn-primary w-100" href="<?= e(url('reception/queue.php?doctor='.$d['id'].'&date='.$date)) ?>"><?= e(t('Open patient queue ↗')) ?></a></article></div><?php endforeach; ?><?php if(!$shown): ?><div class="col-12"><div class="empty-state"><h2><?= e(t('No clinics scheduled')) ?></h2><p><?= e(t('Choose another date to view upcoming queues.')) ?></p></div></div><?php endif; ?></div></main><?php require dirname(__DIR__).'/includes/footer.php'; ?>
